funcs.loadGame:
function(){
 const keys=['auto','1','2','3'].filter(x=>localStorage.getItem(r4SaveKey(x)));
 if(!keys.length)return alert('目前沒有存檔。');
 let best=null,bestTime=0;
 for(const k of keys){try{const d=JSON.parse(localStorage.getItem(r4SaveKey(k)));const t=Date.parse(d.savedAt||0)||0;if(t>=bestTime){best=d;bestTime=t}}catch{}}
 if(!best)return alert('存檔無法讀取。');
 S=best.state;currentPage=best.currentPage||'adventure';r4Ensure();r58Ensure();
 document.getElementById('start').classList.add('hidden');document.getElementById('app').classList.remove('hidden');document.getElementById('advLog').classList.remove('hidden');render()
}

funcs.startNew:
function startNew(){
 const name=(document.getElementById('newName').value.trim()||'無名').slice(0,8), identity=document.getElementById('newIdentity').value;
 S=initialState(name,identity);document.getElementById('start').classList.add('hidden');
 const back=document.getElementById('modalBack'),body=document.getElementById('modalBody'),head=back.querySelector('.modal-head');
 back.classList.remove('hidden');head.classList.add('hidden');
 const scenes=[
  '<b style="font-size:30px">遠古之時</b><br><br>上仙之戰撕裂天穹，靈脈震盪，九州各地留下難以磨滅的痕跡。',
  '漫長歲月過去，王朝、城鎮與修士重新建立秩序。<br><br><span class="gold">然而八隻災獸的封印，正逐漸出現異動。</span>',
  '<span class="muted">東州・大御王朝</span><br><b style="font-size:38px">朝御城</b><br><br>你的修仙之路，從這裡開始。'
 ];
 let idx=0;
 const draw=()=>{
   body.innerHTML=`<div style="min-height:430px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;gap:30px"><div style="font-size:21px;line-height:2;max-width:700px">${scenes[idx]}</div><div class="actions">${idx>0?'<button id="proPrev">上一段</button>':''}${idx<scenes.length-1?'<button id="proNext" class="primary">繼續</button>':'<button id="proStart" class="primary" style="font-size:18px;padding:12px 24px">開始冒險</button>'}</div></div>`;
   if(document.getElementById('proPrev'))document.getElementById('proPrev').onclick=()=>{idx--;draw()};
   if(document.getElementById('proNext'))document.getElementById('proNext').onclick=()=>{idx++;draw()};
   if(document.getElementById('proStart'))document.getElementById('proStart').onclick=()=>{head.classList.remove('hidden');back.classList.add('hidden');S.flags.prologueDone=true;enterGame();log('🌄 你抵達東州・朝御城。')};
 };draw();
}

