funcs.r4Slot:
function(slot){
  const key=r4SaveKey(slot),raw=localStorage.getItem(key);
  if(!raw){
    return `<div class="savecard"><b>${slot==='auto'?'自動存檔':'手動存檔 '+slot}</b><br><span class="muted">空白</span>
      ${S&&slot!=='auto'?`<div class="saveactions"><button class="primary" onclick="r4WriteSave('${slot}')">建立存檔</button></div>`:''}
    </div>`;
  }
  let data=null;try{data=JSON.parse(raw)}catch(e){}
  const st=data?.state||data?.S||data||{};
  const realm=st.realm||'未知';
  const place=st.place||'未知';
  return `<div class="savecard">
    <b>${slot==='auto'?'自動存檔':'手動存檔 '+slot}</b><br>
    <span class="small">${realm}・${place}</span>
    <div class="saveactions">
      <button class="primary" onclick="r541LoadSaveSlot('${slot}')">讀檔</button>
      ${S&&slot!=='auto'?`<button onclick="r4WriteSave('${slot}')">覆蓋</button>`:''}
      <button onclick="r4DeleteSave('${slot}')">刪除</button>
    </div>
  </div>`;
}

funcs.r4ExportSlot:
function r4ExportSlot(slot){
 const raw=localStorage.getItem(r4SaveKey(slot));if(!raw)return;const blob=new Blob([raw],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`九州修仙錄_${slot}_${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)
}

funcs.r4ImportFile:
function r4ImportFile(file){
 const fr=new FileReader();fr.onload=()=>{try{const d=JSON.parse(fr.result);const st=d.state||d;if(!st||!st.name)throw new Error('不是有效的九州修仙錄存檔');S=st;currentPage=d.currentPage||'adventure';localStorage.setItem(r4SaveKey('1'),JSON.stringify({savedAt:new Date().toISOString(),state:S,currentPage}));document.getElementById('start').classList.add('hidden');document.getElementById('app').classList.remove('hidden');document.getElementById('advLog').classList.remove('hidden');r4Ensure();render();alert('讀取存檔成功，並已存入手動存檔1。')}catch(e){alert('讀取存檔失敗：'+e.message)}};fr.readAsText(file)
}

funcs.r4TaskDialog:
function r4TaskDialog(name,questId,phase='accept'){
 let text='';
 if(questId==='tutorial2')text='「先把剛拿到的新手大禮包打開看看。熟悉自己的物品，也是修士最基本的準備。」';
 if(questId==='tour')text='「喔？是新來的道友嗎？歡迎來到朝御城，這兒有布告欄、煉金爐等等的設施，稍微去逛逛吧！」';
 if(questId==='trainingQuest')text='「既然設施都認過了，就去修練場實際運轉一次靈力。別急著求快，先把基礎打穩。」';
 if(questId==='firstBattle')text='「接下來去青陽鎮找林夏于。他好戰歸好戰，但帶新人進實戰倒是很有一套。」';
 if(questId==='firstCombatEntry')text='「走，青陽山就在前面。先別逞強，照我說的做，先看清楚戰鬥介面。」';
 if(questId==='techQuest')text='「光靠拳腳可不夠。這本［初階］靈氣絕你先拿著，打開功法介面自己學。」';
 if(questId==='firstTry')text='「學會了就用。等下你先出手一次，我會收尾。」';
 if(questId==='itemUse')text='「這次先學會挨打時怎麼處理。先防禦，再喝藥，喝藥不會吃掉你這回合的行動。」';
 if(questId==='breakthrough')text='「修為差不多了。回修練介面看看，滿百就試著突破。」';
 if(questId==='confirmCult')text='「回來了。讓我看看你現在的修為。」';
 showModal('📜 任務對話・'+name,`<div class="task-dialogue">${text||'「先照任務目標完成這一步。」'}</div>`)
}

