funcs.r4NpcHasTask:
function r4NpcHasTask(name){
 if(name==='邱山河'){
  if(S.questState.tutorial1.claimed&&!S.quests.some(q=>q.id==='tutorial2'))return true;
  if(S.quests.some(q=>q.id==='tutorial2'&&!q.claimed))return true;
  if(S.quests.some(q=>q.id==='tutorial2'&&q.claimed)&&!S.quests.some(q=>q.id==='tour'))return true;
  if(S.quests.some(q=>q.id==='tour'&&!q.claimed)||S.quests.some(q=>q.id==='tour'&&q.claimed&&!S.quests.some(q=>q.id==='trainingQuest')))return true;
  if(S.quests.some(q=>q.id==='trainingQuest'&&!q.claimed)||S.quests.some(q=>q.id==='returnCity'&&!q.claimed)||S.quests.some(q=>q.id==='confirmCult'&&!q.claimed))return true
 }
 if(name==='林夏于')return S.quests.some(q=>['firstBattle'].includes(q.id)&&!q.claimed)
 return false
}

