funcs.r5StartNew:
function r5StartNew(ev){
 if(ev){ev.preventDefault();ev.stopImmediatePropagation()}
 const name=(document.getElementById('newName').value.trim()||'無名').slice(0,8),identity=document.getElementById('newIdentity').value;
 S=initialState(name,identity);r4Ensure();
 document.getElementById('start').classList.add('hidden');
 const back=document.getElementById('modalBack'),body=document.getElementById('modalBody'),head=back.querySelector('.modal-head');
 back.classList.remove('hidden');head.classList.add('hidden');
 body.innerHTML=`<div id="r5Prologue">
  <div class="sky"></div><div class="cloud c1"></div><div class="cloud c2"></div><div class="mount"></div><div class="seal"></div><div class="flash"></div>
  <div class="titlefx">九州修仙錄</div><div class="caption"></div>
  <div class="controls"><button id="r5Skip">跳過</button><button id="r5Next" class="primary">繼續</button></div>
 </div>`;
 const root=document.getElementById('r5Prologue'),cap=root.querySelector('.caption'),seal=root.querySelector('.seal'),title=root.querySelector('.titlefx');
 const scenes=[
  {cls:'scene-war',text:'遠古之時，上仙交戰，天穹破碎，九州靈脈隨之震盪。'},
  {cls:'scene-war',text:'八隻災獸的力量席捲各州。諸仙以封印鎮住災厄，代價卻是天地靈氣從此紊亂。',seal:true},
  {cls:'scene-city',text:'漫長歲月後，王朝與城鎮重新建立秩序。東州・大御王朝——朝御城。'},
  {cls:'scene-city',text:'而你的修仙之路，將從這裡開始。',title:true}
 ];
 let idx=0,sceneTimer=null,finished=false;
 function draw(){
   if(finished||!root.isConnected)return;
   clearTimeout(sceneTimer);
   root.className=scenes[idx].cls||'';
   cap.classList.remove('show');seal.classList.remove('show');title.classList.remove('show');
   sceneTimer=setTimeout(()=>{
     if(finished||!root.isConnected)return;
     cap.textContent=scenes[idx].text;cap.classList.add('show');
     if(scenes[idx].seal)seal.classList.add('show');
     if(scenes[idx].title)title.classList.add('show');
     document.getElementById('r5Next').textContent=idx===scenes.length-1?'開始冒險':'繼續';
   },180)
 }
 function finish(){
   if(finished)return;finished=true;clearTimeout(sceneTimer);
   head.classList.remove('hidden');back.classList.add('hidden');S.flags.prologueDone=true;enterGame();log('🌄 你抵達東州・朝御城。')
 }
 document.getElementById('r5Next').onclick=()=>{if(idx>=scenes.length-1)finish();else{idx++;draw()}};
 document.getElementById('r5Skip').onclick=finish;draw()
}

