funcs.r53DialogueState:
function r53DialogueState(name){
  S.dialogueState=S.dialogueState||{};
  if(!S.dialogueState[name]){
    S.dialogueState[name]={used:[],charges:5,lastRecoverAt:r4GameMinutes()};
  }
  const st=S.dialogueState[name];
  if(st.charges==null)st.charges=Math.max(0,5-(st.used?.length||0));
  if(st.lastRecoverAt==null)st.lastRecoverAt=r4GameMinutes();
  const elapsed=r4GameMinutes()-st.lastRecoverAt;
  if(elapsed>=180 && st.charges<5){
    const add=Math.min(5-st.charges,Math.floor(elapsed/180));
    st.charges+=add;
    st.lastRecoverAt+=add*180;
    // 允許重新開始下一輪，仍維持句子不重複直到5句用完
    if((st.used||[]).length>=5 && st.charges>0)st.used=[];
  }
  return st;
}

