funcs.r53TravelMinutes:
function r53TravelMinutes(from,to){
  const a=r53MoveGroup(from),b=r53MoveGroup(to);
  // 縮短耗時
  if((a==='city'&&b==='town')||(a==='town'&&b==='city'))return rand(20,40);
  if((a==='town'&&b==='wild')||(a==='wild'&&b==='town'))return rand(15,30);
  if(a==='town'&&b==='town')return rand(25,45);
  return rand(20,40);
}

funcs.r53TravelShouldCount:
function r53TravelShouldCount(from,to){
  S.travelHistory=S.travelHistory||[];
  const h=S.travelHistory;
  // 直接 AB 往返：前兩次算，第三次開始不算
  if(h.length>=2){
    const last=h[h.length-1],prev=h[h.length-2];
    if(prev.from===from && prev.to===to && last.from===to && last.to===from)return false;
  }
  // city > town > wild > town > city 這類來回循環也不算最後回刷
  if(h.length>=3){
    const seq=[h[h.length-3],h[h.length-2],h[h.length-1]];
    if(seq[0].from===to && seq[0].to===seq[2].to && seq[1].to===from && seq[2].from===from && seq[2].to===seq[0].to)return false;
  }
  return true;
}

