funcs.r54InitCenteredDrag:
function r54InitCenteredDrag(viewId,canvasId,key){
 const view=document.getElementById(viewId),canvas=document.getElementById(canvasId);if(!view||!canvas)return;
 let pos=S[key],drag=false,sx=0,sy=0,ox=0,oy=0;
 const center=()=>({x:(view.clientWidth-canvas.offsetWidth)/2,y:Math.min(0,(view.clientHeight-canvas.offsetHeight)/2)});
 if(!pos||!Number.isFinite(pos.x)||!Number.isFinite(pos.y))pos=center();
 const clampPos=()=>{
   const minX=Math.min(0,view.clientWidth-canvas.offsetWidth),minY=Math.min(0,view.clientHeight-canvas.offsetHeight);
   pos.x=clamp(pos.x,minX,0);pos.y=clamp(pos.y,minY,0);canvas.style.transform=`translate(${pos.x}px,${pos.y}px)`;S[key]=pos
 };
 clampPos();
 view.onpointerdown=e=>{if(e.target.closest('.map-node,.sea-island,.sky-island'))return;e.preventDefault();drag=true;sx=e.clientX;sy=e.clientY;ox=pos.x;oy=pos.y;view.setPointerCapture(e.pointerId)};
 view.onpointermove=e=>{if(!drag)return;pos={x:ox+e.clientX-sx,y:oy+e.clientY-sy};clampPos()};
 view.onpointerup=e=>{drag=false;try{view.releasePointerCapture(e.pointerId)}catch{}};
 view.onselectstart=()=>false
}

