funcs.r55RegionBlock:
function r55RegionBlock(z,r,bx,by){
 const main=[bx,by], towns=(r.towns||[]).map((n,i)=>[n,bx+145,by-80+i*80]),
       wild=(r.wild||[]).map((n,i)=>[n,bx+290,by-80+i*80]);
 let nodes=`<div class="route-node main ${S.place===r.main?'current':''}" style="left:${main[0]}px;top:${main[1]}px">${r.main}<br><span class="tiny">${z}</span></div>`, lines='';
 towns.forEach(([n,x,y],i)=>{
   nodes+=`<div class="route-node town ${S.place===n?'current':''}" style="left:${x}px;top:${y}px">${n}</div>`;
   lines+=r55Line(main[0]+42,main[1],x-40,y);
   if(wild[i]){
     const [wn,wx,wy]=wild[i];
     nodes+=`<div class="route-node wild ${S.place===wn?'current':''}" style="left:${wx}px;top:${wy}px">${wn}</div>`;
     lines+=r55Line(x+40,y,wx-40,wy);
   }
 });
 const gateX=bx+430,gateY=by+100;
 if(r.gate){
   nodes+=`<div class="route-node gate ${S.place===r.gate?'current':''}" style="left:${gateX}px;top:${gateY}px">${r.gate}</div>`;
   // 依既有東州規則：第三鄰城 -> 傳送塔
   const feeder=towns[Math.min(2,towns.length-1)];
   if(feeder)lines+=r55Line(feeder[1]+40,feeder[2],gateX-52,gateY,'tele');
   (r.secrets||[]).forEach((s,i)=>{
     const sx=bx+565,sy=gateY+(i-(r.secrets.length-1)/2)*60;
     nodes+=`<div class="route-node secret ${S.place===s?'current':''}" style="left:${sx}px;top:${sy}px">${s}</div>`;
     lines+=r55Line(gateX+50,gateY,sx-45,sy,'tele');
   });
 }
 if(r.danger){
   const dx=bx-5,dy=by+105;
   nodes+=`<div class="route-node danger ${S.place===r.danger?'current':''}" style="left:${dx}px;top:${dy}px">${r.danger}</div>`;
   lines+=r55Line(main[0],main[1]+28,dx,dy-24,'danger');
 }
 return lines+nodes
}

