funcs.r58RecoverTrainingCharges:
function r58RecoverTrainingCharges(){
 r58Ensure();
 for(const key of ['ground','meditation']){
   const st=S.trainingSystem[key];
   if(st.charges>=st.max){st.anchor=S.effectiveMinutes||0;continue}
   const elapsed=(S.effectiveMinutes||0)-st.anchor;
   if(elapsed>=360){
     const add=Math.min(st.max-st.charges,Math.floor(elapsed/360));
     st.charges+=add;st.anchor+=add*360
   }
 }
}

