funcs.r510RecoverEnergy:
function r510RecoverEnergy(){
 r510CraftEnsure();const now=r4GameMinutes();
 for(const k of ['alchemy','forge']){
   const x=S.personalCraft[k];
   if(x.energy>=x.max){x.lastAt=now;continue}
   const steps=Math.floor((now-x.lastAt)/120);
   if(steps>0){x.energy=Math.min(x.max,x.energy+steps*10);x.lastAt+=steps*120}
 }
}

