funcs.v070SixCoreBonus:
function v070SixCoreBonus(){
 // 先以角色目前六核相對「本境界進入時自身基準」的累積表現計算；基準存檔後固定，不因裝備臨時變動重寫。
 S.realmCoreBaseline=S.realmCoreBaseline||{};const r=v070RealmInfo().name;
 if(!S.realmCoreBaseline[r])S.realmCoreBaseline[r]={hp:S.maxhp||S.hp||1,mp:S.maxmp||S.mp||1,atk:S.atk||1,def:S.def||1,agi:S.agi||1,hit:S.hit||1};
 const b=S.realmCoreBaseline[r],ratio=(S.maxmp/b.mp)*.30+(S.hit/b.hit)*.25+(S.maxhp/b.hp)*.15+(S.def/b.def)*.15+(S.atk/b.atk)*.10+(S.agi/b.agi)*.05;
 const pct=ratio*100;if(pct<100)return 0;if(pct<110)return 2;if(pct<120)return 4;if(pct<130)return 6;if(pct<140)return 8;if(pct<150)return 10;return 12;
}

