  for(const [id,d] of Object.entries(R56_QUESTS||{})){
    if(d.type!=='主線'||d.npc!==name||r56Has(id))continue;
    // 只有前置已完成，但額外條件尚未達標時，視為「下一個主線」灰色提示
    const prereqOK=!d.prereq||r56IsClaimed(d.prereq);
    if(!prereqOK)continue;
    if(d.realm&&!r56RealmAtLeast(d.realm))return id;
  }
  return null;
}

funcs.r519ApplyNpcQuestMarks:
function r519ApplyNpcQuestMarks(){
  document.querySelectorAll('.r519-qmark').forEach(el=>{
    el.classList.remove('r519-qmark','r519-main-ready','r519-main-locked','r519-side-ready','r519-commission-ready');
  });
  const names=Object.keys(R511_NPC||{});
  const cards=[...document.querySelectorAll('#page .card,#page .r514-npc-list-card')];
  for(const card of cards){
    const txt=(card.textContent||'');
    const name=names.find(n=>txt.includes(n));if(!name)continue;
    const types=r519QuestOfferTypes(name);
    let cls='';
    if(types.has('主線'))cls='r519-main-ready';
    else if(r519NextLockedMain(name))cls='r519-main-locked';
    else if(types.has('支線'))cls='r519-side-ready';
    else if(types.has('委託'))cls='r519-commission-ready';
    if(cls)card.classList.add('r519-qmark',cls);
  }
}

