funcs.r541RobberyChance:
function r541RobberyChance(name){
  const d=r541MajorMinorDelta(name);
  let chance=40;
  if(d.major>=2)chance+=35;
  else if(d.major===1)chance+=20;
  else if(d.major===-1)chance-=25;
  else if(d.major<=-2)chance-=40;
  else{
    const minorStep=Math.min(3,Math.floor(Math.abs(d.minor)/3));
    chance+=(d.minor<0?-1:1)*minorStep*5;
  }
  const shop=r541ShopState(name);
  const wallet=Math.max(0,shop.wallet);
  const ratio=wallet<=0?999:Number(S.coins||0)/wallet;
  if(ratio>=3)chance+=20;
  else if(ratio>=2)chance+=15;
  else if(ratio>=1.25)chance+=10;
  else if(ratio>=.75)chance+=0;
  else if(ratio>=.50)chance-=10;
  else if(ratio>=.25)chance-=15;
  else chance-=20;
  return Math.max(5,Math.min(95,chance));
}

