funcs.r542SyncFatigueStatus:
function r542SyncFatigueStatus(){
  if(!window.S)return;
  r542EnsureOutsideStatus();

  const fatigue=Math.max(0,Number(S.fatigue||0));
  const idx=S.outsideStatus.findIndex(x =>
    x && (
      x.id==='fatigue_exhausted' ||
      x.name==='勞累' ||
      x.name==='［勞累］'
    )
  );

  if(fatigue>=100){
    const data={
      id:'fatigue_exhausted',
      name:'勞累',
      desc:'疲勞達100；身 -10%，無法修練。疲勞降至99以下時自動解除。',
      curableByClinic:false,
      source:'fatigue'
    };
    if(idx<0){
      S.outsideStatus.push(data);
    }else{
      S.outsideStatus[idx]=Object.assign({},S.outsideStatus[idx],data);
    }
    S.fatigueStatus=true;
  }else{
    S.outsideStatus=S.outsideStatus.filter(x =>
      !(x && (
        x.id==='fatigue_exhausted' ||
        x.name==='勞累' ||
        x.name==='［勞累］'
      ))
    );
    S.fatigueStatus=false;
  }
}

