funcs.JZFormalPower:
function r548Power(x){
  const preset=Number(x?.combatPower??x?.battlePower??x?.戰鬥力);
  if(Number.isFinite(preset)&&preset>0)return Math.round(preset);
  const s=r548Eight(x),main=Math.max(Number(s.atk||0),Number(s.dao||0)),sub=Math.min(Number(s.atk||0),Number(s.dao||0));
  const eh=Math.max(0,Number(x?.effectHit||0)-100),er=Math.max(0,Number(x?.effectResist||0)-100),cr=Math.max(0,Number(x?.critRate||5)-5),cd=Math.max(0,Number(x?.critDamage||150)-150);
  return Math.max(1,Math.round(Number(s.maxhp||0)*.10+Number(s.maxmp||0)*.08+main*2.4+sub*.85+Number(s.def||0)*2+Number(s.daoDef||0)*2+Number(s.agi||0)*1.5+Number(s.hit||0)*1.3+eh*2+er*2+cr*8+cd*2));
}

