funcs.r553NormalizeRootWidgets:
function r553NormalizeRootWidgets(scope=document){
  const old=[...scope.querySelectorAll('.r521-root-orb')];
  for(const el of old){
    let root=el.dataset.root||'';
    if(!root){
      const txt=(el.getAttribute('title')||el.getAttribute('aria-label')||el.querySelector('img')?.alt||'');
      root=['火','水','風','土','木','雷','光','暗'].find(x=>txt.includes(x))||'';
    }
    const src=root?(R521_ROOT_ICON||{})[root]:el.querySelector('img')?.getAttribute('src');
    if(!src)continue;
    el.classList.add('r553-root-widget');
    el.dataset.root=root;
    el.style.backgroundImage='none';

    // 只允許一個底座。
    let bases=[...el.querySelectorAll(':scope > .r553-root-base')];
    let base=bases.shift();
    bases.forEach(x=>x.remove());
    if(!base){base=document.createElement('span');base.className='r553-root-base';base.setAttribute('aria-hidden','true');el.prepend(base);}

