funcs.r559ResetCrimeTimer:
function r559ResetCrimeTimer(reason='犯罪'){
    const d=r559EnsureWantedDecay();
    if(!d)return;
    const now=r559Now();
    d.lastCrimeAt=now;
    /* 先完整等待3日；第3日結束後才開始計算「每經過1日 -20」 */
    d.lastDecayAt=now + R559_GRACE_MINUTES;
    d.lastSeenWanted=Number(S.wanted||0);
    d.lastCrimeReason=reason;
    d.lastCrimeResetAt=now;
  }

funcs.r559ProcessWantedDecay:
function r559ProcessWantedDecay(){
    const d=r559EnsureWantedDecay();
    if(!d)return;
    let wanted=Math.max(0,Number(S.wanted||0));
    const now=r559Now();

    if(wanted<=0){
      S.wanted=0;
      d.lastSeenWanted=0;
      return;
    }

    const graceEnd=Number(d.lastCrimeAt||0)+R559_GRACE_MINUTES;
    if(now<=graceEnd){
      d.lastSeenWanted=wanted;
      return;
    }

    /* lastDecayAt = 無犯罪3日的終點。
       只有再完整經過1日才扣第一次20，所以第一扣發生在第4個完整無犯罪遊戲日。 */
    const base=Math.max(graceEnd,Number(d.lastDecayAt||graceEnd));
    const elapsed=now-base;
    if(elapsed < R559_DECAY_STEP_MINUTES){
      d.lastSeenWanted=wanted;
      return;
    }

    const steps=Math.floor(elapsed/R559_DECAY_STEP_MINUTES);
    if(steps<=0)return;

    const before=wanted;
    wanted=Math.max(0,wanted - steps*R559_DECAY_AMOUNT);
    S.wanted=wanted;
    d.lastDecayAt=base + steps*R559_DECAY_STEP_MINUTES;
    d.lastSeenWanted=wanted;

    const reduced=before-wanted;
    if(reduced>0){
      try{ log(`📉 已連續3個遊戲日未再次犯罪；通緝自然衰減 ${before} → ${wanted}（-${reduced}）。`); }catch(e){}
    }
  }

