methods.resolve:
function resolve(b,a,r,targets,ctx={}){globalThis.JZW?.beforeResolve(b,a,r);const hasDamage=r.ops.some(o=>['damage','mainHit','coreStrike','ownElement'].includes(o.op)),main=ctx.main||targets[0],reflection=new Map(targets.map(t=>[t,!!has(t,'迴能')])),usedReflection=new Set();
  ctx={selfHP:a.hp/stat(a,'maxhp'),beforeMP:stat(a,'maxmp'),bestKind:stat(a,'dao')>stat(a,'atk')?'magic':'physical',startStates:new Map(targets.map(t=>[t,allStates(t).map(s=>s.name)])),charge:has(a,'蓄勢'),thunderCharge:has(a,'充能'),...ctx};
  const hostile=r.ops.filter(o=>o.op==='status'&&o.hostile);
  function applyHostile(t,op){if(!alive(t))return;const p=effectChance(b,a,t,op);if(rng()>=p){event(b,{type:'resist',target:t.name,name:op.name});log(b,`${t.name}抵抗「${op.name}」。`);return;}
   const reflect=reflection.get(t),dest=reflect?a:t;if(reflect&&!usedReflection.has(t)){usedReflection.add(t);remove(t,'迴能');log(b,`${t.name}「迴能」返還本招減益，僅反彈一次。`);}
   if(reflect&&has(dest,'免疫')?.types?.some(n=>n==='*'||n===op.name))return;add(b,reflect?t:a,dest,op);
  }
  for(const op of r.ops){if(globalThis.JZP?.resolveOp(b,a,r,op,targets,ctx))continue;const ts=op.to==='self'?[a]:op.op==='mainHit'?[main]:targets;
   for(const t of ts){if(!alive(t))continue;
    if(op.op==='damage'||op.op==='mainHit'){
     if(rng()>=hitChance(a,t,r)){globalThis.JZR?.onDodge(b,t);event(b,{type:'miss',actor:a.name,target:t.name});log(b,`${a.name}對${t.name}的攻擊未命中。`);continue;}
     b.jz072DamageKind=op.kind||ctx.bestKind;b.jzwCurrentElements=op.element??r.element??[];const critical=rng()<critChance(a,t);hurt(b,a,t,damageValue(a,t,op,r,{...ctx,crit:critical}));if(critical)globalThis.JZW?.onCrit(b,a);globalThis.JZR?.onImpact(b,a,t,r,op);
     for(const effect of hostile)applyHostile(t,effect);
    }else if(op.op==='heal'){const ratio=op.condition&&t.hp/stat(t,'maxhp')<=op.condition.targetHP?op.condition.ratio:op.ratio;restore(b,a,t,stat(a,'dao')*ratio+stat(a,'maxmp')*(op.mpRatio||0),false,r.id==='T052'?false:rng()<critChance(a,t,true));
    }else if(op.op==='mana'){restore(b,a,t,(op.beforeMax?ctx.beforeMP:stat(t,'maxmp'))*op.ratio,true);
    }else if(op.op==='cleanse'){const list=init(t).debuffs;if(op.count){for(const state of list.slice(-op.count))remove(t,state.name);}else for(const n of op.names)remove(t,n);event(b,{type:'cleanse',target:t.name});
    }else if(op.op==='status'){if(op.hostile){if(!hasDamage)applyHostile(t,op);}else{add(b,a,t,op);if(t===a&&op.name==='蓄勢')ctx.charge=has(a,'蓄勢');}
    }else if(op.op==='selfDestruct'){init(a).bomb={target:t,round:b.round};globalThis.JZP?.bombPrepared(b,a,t);event(b,{type:'prepare',actor:a.name,target:t.name});log(b,`${a.name}開始準備自爆，下次行動引爆。`);}
   }
  }
  if(ctx.charge&&(hasDamage||byId[ctx.charge.skillId]?.name==='狼嚎'))remove(a,'蓄勢');if(ctx.thunderCharge&&hasDamage&&r.element?.includes('雷'))remove(a,'充能');globalThis.JZW?.afterResolve(b,a,r,targets,ctx);
 }

methods.repairGear:
()=>{if(!S)return;S.gearInventory??={};const source=S.equipment||{},out=Object.fromEntries(M.slots.map(k=>[k,'無']));
 const move=(key,n)=>{if(!n||n==='無')return;const slot=M.slot(n)||aliases[key];if(slot&&out[slot]==='無')out[slot]=n;else{const old=S.gearInventory[n];if(old&&typeof old==='object')old.count=Number(old.count||0)+1;else S.gearInventory[n]=Number(old||0)+1;}};
 for(const k of M.slots)move(k,source[k]);for(const [k,n] of Object.entries(source))if(!M.slots.includes(k))move(k,n);
 if(JSON.stringify(source)!==JSON.stringify(out))S.equipment=out;
}

methods.cleanUI:
()=>{for(const root of [document.getElementById('page'),document.getElementById('questPanel'),document.getElementById('modalBody')]){if(!root)continue;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let t;while(t=walker.nextNode()){if(/^(SCRIPT|STYLE|TEXTAREA)$/.test(t.parentElement?.tagName))continue;const value=t.nodeValue.replace(/\b(?:MQ|SQ|CQ)-DZ-\d+(?:-\d+|-[A-Z])?(?:-\d+)?\b\s*[・：]?\s*/g,'');if(value!==t.nodeValue)t.nodeValue=value;}}
 for(const c of document.querySelectorAll('#modalBody .weapon-choice')){const n=U.short(c.querySelector('b')?.textContent||'');if(M.weaponDescriptions[n]&&!c.querySelector('.weapon-tag')){const span=document.createElement('span');span.className='weapon-tag';span.textContent=M.weaponDescriptions[n];c.querySelector('button')?.before(span,document.createElement('br'));}}
 for(const b of document.querySelectorAll('button[onclick*="jzPartnerEdit"]')){b.classList.remove('r518-quest-target');b.closest('.card')?.classList.remove('r518-quest-target');}
}
